{
 "research_concepts": [
  "DRIVE (basketball play type)",
  "Pick and Roll (PNR) (basketball play type)",
  "Play sequencing (basketball)",
  "Points Per Possession (PPP)",
  "Offensive efficiency",
  "Contextual effects on play outcomes"
 ],
 "methodological_questions": [
  "How to define 'preceding' in play sequences?",
  "How to establish a baseline for comparison in play-type efficiency studies?",
  "What are known confounders when analyzing sequential play effects on offensive efficiency?",
  "What are the reliability and validity of derived play-type labels?"
 ],
 "historical_evidence": [
  {
   "id": "FAM:SF-APPS-010",
   "status_as_recorded": "inconclusive",
   "finding": "DRIVE PPP is stable or improves across playoff series; observational with selection caveats."
  },
  {
   "id": "FAM:SF-APPS-011",
   "status_as_recorded": "supported",
   "finding": "DRIVE PPP is materially higher in regular season (1.198) than playoffs (0.912), a difference of -0.286 across 25 teams; PNR also shows a -0.173 difference."
  },
  {
   "id": "FAM:SF-PAP-096",
   "status_as_recorded": "artifact",
   "finding": "Play-type classifier assisted-flag leak caused SPOT_UP to have 2.83 PPP (100% makes) because the assisted flag only existed on makes; after rewrite SPOT_UP ~1.16, TRANSITION ~1.20."
  },
  {
   "id": "FAM:SF-APPA-050",
   "status_as_recorded": "not a hypothesis test",
   "finding": "PUTBACK is a top suppressor for 6+ stars' next-possession PPP; no multiplicity correction, and small sample sizes (n_after is 32-95) were noted."
  },
  {
   "id": "FAM:SF-CHT-025",
   "status_as_recorded": "artifact",
   "finding": "OTHER play type PPP was inflated by 36% foul endings (FOUL_BUCKET); DRIVE PPP was 12pp below a foul benchmark (FOUL_LEAK); PNR showed a 22% foul rate. Only 0.7% of possessions mapped to a real play type via initiation_type."
  },
  {
   "id": "FAM:SF-APPS-014",
   "status_as_recorded": "rejected",
   "finding": "DRIVE efficiency rises early-to-late (+0.078 G1, +0.093 all games) within a game, instead of dropping."
  },
  {
   "id": "FAM:SF-APPM-014",
   "status_as_recorded": "not a hypothesis test",
   "finding": "Audit overall FAIL: OTHER play type 20.2% vs <10% target; 40.8% low confidence; DRIVE foul-draw 1.7% vs 14-22% benchmark; most play types PPP above benchmark band; play type labels have systematic issues that undermine adaptation findings."
  },
  {
   "id": "FAM:SF-APPS-012",
   "status_as_recorded": "not a hypothesis test",
   "finding": "DRIVE allowed PPP was lower in playoffs (0.923) than regular season (1.191), a difference of -0.268; PNR allowed PPP was -0.139. PNR share jumped +12.1pp, potentially reflecting tagging differences."
  },
  {
   "id": "FAM:SF07",
   "status_as_recorded": "supported",
   "finding": "Sequential pair premiums and defensive aftershocks were observed for 8/8 play types, including DRIVE (+0.123 PPP aftershock) and PNR (+0.127 PPP aftershock), after successful plays."
  },
  {
   "id": "FAM:SF-APPM-058",
   "status_as_recorded": "not a hypothesis test",
   "finding": "PNR shot-level season rates were used as calibration input for PBPProxyPNR, with calibrated PNR ~17.9-19.6% of possessions."
  }
 ],
 "failed_approaches": [
  {
   "id": "FAM:SF-PAP-096",
   "what_failed": "Sequence-level PPP by inferred play type before rewriting play_type_inferrer.py",
   "why": "C_artifact (apparent effect produced by a construction, selection or labelling flaw)"
  },
  {
   "id": "FAM:SF-CHT-025",
   "what_failed": "Per-PT diagnostic of foul-ending share vs PPP; initiation_type mapping",
   "why": "C_artifact (apparent effect produced by a construction, selection or labelling flaw)"
  },
  {
   "id": "FAM:SF-APPM-014",
   "what_failed": "Audit of inferred play-type labels against benchmark volumes, foul rates, PPP and known team identities",
   "why": "C_artifact (apparent effect produced by a construction, selection or labelling flaw)"
  },
  {
   "id": "FAM:SF-APPA-050",
   "what_failed": "Analysis of superstar sequential suppression",
   "why": "E_unclear (mechanism unclear from the records)"
  }
 ],
 "evidence_establishes": [
  "Play-type labels, particularly for DRIVE and PNR, have historically suffered from systematic issues, including artifacts related to foul leakage, assisted flag mechanics, and general inaccuracies (FAM:SF-PAP-096, FAM:SF-CHT-025, FAM:SF-APPM-014, FAM:SF-APPS-012).",
  "DRIVE PPP varies significantly by context (e.g., regular season vs. playoffs, within-game progression) (FAM:SF-APPS-011, FAM:SF-APPS-014).",
  "Sequential effects on PPP for various play types, including DRIVE and PNR, have been observed, where a preceding successful play can lead to an 'aftershock' of higher PPP for the subsequent play (FAM:SF07)."
 ],
 "evidence_does_not_establish": [
  "The specific causal effect or correlation of a *teammate DRIVE* immediately preceding a *PNR* on PNR PPP.",
  "Whether the current play-type labeling system has resolved the previously identified systematic issues for DRIVE and PNR.",
  "The appropriate methodological approach to account for potential confounding factors in sequential play analysis, beyond general observations of small sample sizes and lack of multiplicity correction in related studies (FAM:SF-APPA-050)."
 ],
 "own_inferences": [
  "The research question is fundamentally about a sequential effect, similar in nature to studies that found 'aftershocks' (FAM:SF07), suggesting such effects can exist.",
  "However, the historical evidence strongly implies that the core data (DRIVE and PNR play-type labels) is likely unreliable and prone to artifacts, making direct testing of the question as posed highly risky.",
  "A robust test would require significant preprocessing to validate and potentially correct play-type labels, or to use a more resilient methodology that is less susceptible to these known labeling flaws."
 ],
 "uncertainties": [
  "The current state of the play-type labeling system and whether the issues identified in FAM:SF-PAP-096, FAM:SF-CHT-025, and FAM:SF-APPM-014 have been fully addressed and validated.",
  "The frequency of the specific sequence 'teammate DRIVE preceding PNR', which could impact sample size and statistical power.",
  "The precise definition of 'preceding' (e.g., immediate prior possession, within a certain time window, or across dead balls)."
 ],
 "historical_effect": {
  "changed_decision": "yes",
  "explanation": "The historical evidence significantly changed the decision. Without it, the question would appear directly testable. However, the retrieved records reveal severe, recurrent, and fundamental data quality issues with play-type labels for DRIVE and PNR (FAM:SF-PAP-096, FAM:SF-CHT-025, FAM:SF-APPM-014, FAM:SF-APPS-012). These issues mean that any direct analysis of the question as posed would likely yield artifactual results or be inconclusive due to unreliable measurements. The decision shifted from 'proceed' to 'proceed_with_changes' to address these data quality prerequisites."
 },
 "testability": {
  "p_testable": 0.3,
  "blocking_constraints": [
   {
    "code": "LABEL_ERROR",
    "text": "Historical evidence (FAM:SF-PAP-096, FAM:SF-CHT-025, FAM:SF-APPM-014, FAM:SF-APPS-012) repeatedly highlights severe and systematic issues with DRIVE and PNR play-type labels, including foul leakage, low confidence, and inaccurate foul rates. These make the core variables of the research question highly unreliable."
   }
  ]
 },
 "prior_work": {
  "already_answered": "no",
  "cited": [
   "FAM:SF07"
  ],
  "summary": "While FAM:SF07 established that sequential effects ('aftershocks') on PPP exist for DRIVE and PNR generally, it did not test the specific interaction of a *teammate DRIVE* preceding a *PNR* on PNR PPP. The broader context of play-type label reliability issues has been extensively studied, but not this specific question."
 },
 "risks": [
  {
   "code": "LABEL_ERROR",
   "text": "The most significant risk. Play-type labels for DRIVE and PNR have known systematic issues (e.g., foul leakage, low confidence, inaccurate foul rates, assisted flag artifacts) that could lead to spurious findings or mask a true effect. The reliability of these labels is critical for the question."
  },
  {
   "code": "CONFOUNDING",
   "text": "Many factors could confound the relationship, such as specific players involved (initiator, screener), team offensive schemes, game situation (score, clock), defensive strategy, and the outcome of the preceding DRIVE itself (e.g., successful drive leading to kick-out vs. unsuccessful drive leading to reset). These unobserved or uncontrolled factors could drive observed differences in PNR PPP."
  },
  {
   "code": "EXPOSURE_SPARSITY",
   "text": "The specific sequence of 'teammate DRIVE immediately preceding a PNR' might be relatively rare, leading to small sample sizes for the treatment group and insufficient statistical power to detect an effect, if one exists (similar to issues in FAM:SF-APPA-050)."
  },
  {
   "code": "RTM_SELECTION",
   "text": "Teams might choose to run a PNR after a DRIVE for specific strategic reasons (e.g., a defensive breakdown, a failed initial action). This selection bias could make it appear that the DRIVE 'caused' a change in PNR PPP, when in fact it's a strategic response to the situation created by the DRIVE."
  },
  {
   "code": "DRIFT_NONSTATIONARITY",
   "text": "Over multiple seasons (2022-23 to 2025-26), play-type definitions, player roles, team strategies, or the underlying data generation process could change, introducing non-stationarity into the data and potentially biasing results."
  }
 ],
 "predicted_outcome": {
  "supported": 0.1,
  "rejected": 0.1,
  "untestable": 0.3,
  "artifact": 0.4,
  "uncertain": 0.1
 },
 "decision": "proceed_with_changes",
 "design": {
  "estimand": "The causal effect of a teammate DRIVE on the immediately subsequent PNR possession's Points Per Possession (PPP).",
  "unit": "Offensive possession, specifically a PNR possession.",
  "sample": "All PNR possessions from NBA 2022-23 to 2025-26 regular seasons and playoffs. The 'treatment' group will be PNR possessions immediately preceded by a teammate DRIVE (on the same offensive sequence). The 'control' group will be PNR possessions not immediately preceded by a teammate DRIVE (e.g., preceded by other play types, or a dead ball).",
  "power": "Power analysis will be conducted after initial data exploration to determine the frequency of the 'DRIVE -> PNR' sequence and the variance of PNR PPP. A minimum detectable effect size will be specified (e.g., +/- 0.05 PPP) with 80% power at alpha=0.05. If sample sizes for the 'treatment' group are too small (e.g., < 1000 possessions), the study will be deemed underpowered.",
  "controls": "Control for player identity (PNR ball-handler, screener), defensive matchup, game state (score differential, quarter, time remaining), team and opponent identity, season, and the outcome/success of the preceding DRIVE (e.g., shot attempt, foul drawn, turnover, success/failure based on score change). Use a regression framework (e.g., mixed-effects model) to account for hierarchical structure (player, team, game).",
  "falsification": "Prior to analysis, conduct a thorough audit and, if necessary, correction of play-type labels for DRIVE and PNR, specifically focusing on the issues highlighted in historical evidence (foul leakage, assisted flag artifacts, general low confidence). This includes cross-referencing with raw play-by-play data and potentially manual review of a sample. Test for 'null' effects by examining other, theoretically unrelated preceding play types to ensure no spurious correlations arise from the methodology. If the label audit reveals unresolvable issues, the study will be halted.",
  "multiplicity": "Given a single primary hypothesis, standard alpha=0.05 will be used. If exploratory analyses of other preceding play types are conducted, appropriate multiplicity corrections (e.g., Bonferroni, FDR) will be applied.",
  "decision_rule": "The hypothesis will be considered 'supported' if the estimated effect of a preceding teammate DRIVE on PNR PPP is statistically significant (p < 0.05) in the hypothesized direction (positive), and the magnitude is considered practically meaningful (e.g., > 0.03 PPP), after controlling for confounders and passing falsification checks. If the effect is significant in the opposite direction, the hypothesis will be 'rejected'. If the effect is not significant or the study is underpowered/fails falsification, it will be 'inconclusive' or 'artifact'.",
  "data_version": "NBA 2022-23 regular season and playoffs, NBA 2023-24 regular season and playoffs, NBA 2024-25 regular season and playoffs, NBA 2025-26 regular season (complete from 2026-04-13), NBA 2025-26 playoffs (complete from 2026-06-21)."
 }
}

